def separate_paren_groups(paren_string: str) -> list:
    paren_string = paren_string.replace(" ", "")
    results = []
    stack = []
    current_group = []

    for char in paren_string:
        current_group.append(char)
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack.pop()

        if not stack and current_group:
            results.append(''.join(current_group))
            current_group = []

    return results

