def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill in the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize a 4D DP table
    dp = [[[[0] * N for _ in range(N)] for _ in range(N)] for _ in range(N)]

    # Start filling the DP table
    for i in range(N):
        for j in range(N):
            for k in range(i+1):
                l = j + i - k
                if l < 0 or l >= N:
                    continue
                # Both paths are at the start
                if i == 0 and k == 0:
                    dp[0][0][0][0] = grid[0][0]
                else:
                    # Calculate the maximum value for the current state
                    current_value = max(
                        dp[i-1][j][k-1][l] if i > 0 and k > 0 else float('-inf'),
                        dp[i][j-1][k][l-1] if j > 0 and l > 0 else float('-inf'),
                        dp[i-1][j][k][l] if i > 0 else float('-inf'),
                        dp[i][j-1][k-1][l] if j > 0 and k > 0 else float('-inf')
                    )
                    if i != k or j != l:
                        current_value += grid[i][j] + grid[k][l]
                    else:
                        current_value += grid[i][j]
                    dp[i][j][k][l] = current_value

    return dp[N-1][N-1][N-1][N-1]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x-1, y-1)] = value

    # Initialize a 4D dp table
    dp = [[[[0] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)] for _ in range(N + 1)]

    for i in range(N):
        for j in range(N):
            for k in range(N):
                l = i + j - k
                if l < 0 or l >= N:
                    continue
                current_value = grid[(i, j)] + (grid[(k, l)] if (i != k or j != l) else 0)
                dp[i+1][j+1][k+1][l+1] = max(
                    dp[i][j+1][k][l+1],
                    dp[i][j+1][k+1][l],
                    dp[i+1][j][k][l+1],
                    dp[i+1][j][k+1][l]
                ) + current_value

    return dp[N][N][N][N]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from functools import lru_cache

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x - 1][y - 1] = value

    @lru_cache(None)
    def dp(r1, c1, r2):
        c2 = r1 + c1 - r2
        if r1 >= N or r2 >= N or c1 >= N or c2 >= N or grid[r1][c1] == -1 or grid[r2][c2] == -1:
            return float('-inf')
        if r1 == c1 == N - 1:
            return grid[r1][c1]

        current_value = grid[r1][c1] if (r1, c1) == (r2, c2) else grid[r1][c1] + grid[r2][c2]

        # Move down or right
        return current_value + max(
            dp(r1 + 1, c1, r2 + 1),  # both down
            dp(r1 + 1, c1, r2),       # p1 down, p2 right
            dp(r1, c1 + 1, r2 + 1),   # p1 right, p2 down
            dp(r1, c1 + 1, r2)        # both right
        )

    return max(0, dp(0, 0, 0))

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
