    dp[1][1][1][1] = grid[0][0]

    # Fill the DP array
    for i1 in range(1, N + 1):
        for j1 in range(1, N + 1):
            for i2 in range(1, N + 1):
                j2 = i1 + j1 - i2
                if j2 < 1 or j2 > N:
                    continue
                if grid[i1-1][j1-1] == -1 or grid[i2-1][j2-1] == -1:
                    continue
                if i1 > 1 and i2 > 1:
                    dp[i1][j1][i2][j2] = max(dp[i1-1][j1][i2-1][j2], dp[i1][j1][i2-1][j2-1], dp[i1-1][j1][i2][j2-1], dp[i1-1][j1-1][i2-1][j2-1]) + grid[i1-1][j1-1]
                elif i1 > 1:
                    dp[i1][j1][i2][j2] = dp[i1-1][j1][i2][j2-1] + grid[i1-1][j1-1]
                elif i2 > 1:
                    dp[i1][j1][i2][j2] = dp[i1][j1][i2-1][j2-1] + grid[i2-1][j2-1]
                else:
                    continue
                if i1 != i2 or j1 != j2:
                    dp[i1][j1][i2][j2] += grid[i2-1][j2-1]

    # Return the maximum value collected
    return max(dp[N][N][N][N], 0)

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary for quick access
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x - 1, y - 1)] = value

    # Initialize DP table with -inf
    dp = [[[-float('inf')] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0][0] = 0

    # Fill the DP table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                j2 = i1 + j1 - i2  # The sum of indices must be the same for both paths
                if j2 < 0 or j2 >= N or grid[(i1, j1)] == 0 or grid[(i2, j2)] == 0:
                    continue
                if i1 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1 - 1][j1][i2])
                if j1 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1 - 1][i2])
                if i2 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1][i2 - 1])
                if j2 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1][i2][j2 - 1])

                if i1 == i2 and j1 == j2:
                    dp[i1][j1][i2] += grid[(i1, j1)]
                else:
                    dp[i1][j1][i2] += grid[(i1, j1)] + grid[(i2, j2)]

    return max(0, dp[N - 1][N - 1][N - 1])

