def cantor_numbering(N: int) -> str:
    diagonal = 1
    while N > diagonal:
        N -= diagonal
        diagonal += 1
    if diagonal % 2 == 0:
        return f"{N}/{diagonal - N + 1}"
    else:
        return f"{diagonal - N + 1}/{N}"

