def max_product(num_str: str, N: int, K: int) -> int:
    def find_max_product(start, end, remaining_k):
        if remaining_k == 0:
            return int(num_str[start:end])

        max_product = 0
        for i in range(start + 1, end - remaining_k + 1):
            left_product = int(num_str[start:i])
            right_product = find_max_product(i, end, remaining_k - 1)
            max_product = max(max_product, left_product * right_product)

        return max_product

    return find_max_product(0, N, K)

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_product = 0
        for i in range(start + 1, N - (k - 1)):
            left = int(num_str[start:i])
            right = helper(i, k - 1)
            max_product = max(max_product, left * right)
        return max_product

    return helper(0, K)

