def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    dp = [0] * (n + 1)
    for price, importance in items:
        for j in range(n, price - 1, -1):
            dp[j] = max(dp[j], dp[j - price] + price * importance)
    return max(dp)

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a DP array to store the maximum importance value for each budget up to n
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the DP array from right to left to avoid using the current item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * importance)

    # The maximum importance value within the budget is the last element in the dp array
    return dp[n]

