def max_energy(beads):
    n = len(beads)
    beads = beads + beads  # Extend the list to handle the circular nature
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    def merge(i, j):
        if i == j - 2:
            return beads[i] * beads[i + 1] * beads[j]
        return max(dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j] for k in range(i + 1, j))

    for length in range(3, n + 2):  # length is the length of the substring + 1
        for i in range(n):
            j = i + length - 1
            if j < 2 * n:
                dp[i][j] = merge(i, j)

    return max(dp[i][i + n - 1] for i in range(n))

