    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the DP array where dp[i] is True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    # Fill the DP array
    for volume in volumes:
        # Traverse the dp array backwards to avoid using the same volume multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be formed which is less than or equal to V
    max_occupied_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied_volume = i
            break

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - max_occupied_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array to store the maximum volume that can be achieved with the given capacity
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a volume of 0 is always achievable

    # Iterate over each item
    for v in volumes:
        # Update the DP array from the back to avoid using the same item multiple times
        for j in range(V, v - 1, -1):
            if dp[j - v]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding the box's capacity
    max_achievable_volume = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_achievable_volume = j
            break

    # The minimum remaining space is the difference between the total capacity and the maximum achievable volume
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i-1][j]
            for k in range(1, min(a[i-1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i-1][j-k]) % MOD

    return dp[n][m]

