def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Create two arrays to store the length of the longest increasing subsequence ending at each position
    # and the longest decreasing subsequence starting at each position
    left = [1] * n
    right = [1] * n

    # Fill left array
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                left[i] = max(left[i], left[j] + 1)

    # Fill right array
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                right[i] = max(right[i], right[j] + 1)

    # Calculate the minimum number of students to leave
    max_choir = 0
    for i in range(n):
        max_choir = max(max_choir, left[i] + right[i] - 1)

    return n - max_choir

