        return 0

    left = [1] * n
    right = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left[i] = left[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right[i] = right[i + 1] + 1

